use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Tool { pub id: u64, pub name: String, pub zone: String }
#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Workshop {
    pub name: String,
    pub zones: BTreeMap<String, Vec<u64>>,
    pub tools: BTreeMap<u64, Tool>,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Command {
    Health, Summary, Zone(String), AddZone(String), RemoveZone(String),
    Tool(u64), AddTool { id: u64, name: String, zone: String }, RemoveTool(u64),
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Reply { Text(String), Changed, NotFound, Conflict, Invalid }

pub fn dispatch(workshop: &mut Workshop, command: Command) -> Reply {
    match command {
        Command::Health => Reply::Text("ready".into()),
        Command::Summary => Reply::Text(format!("{}|{}", workshop.name, workshop.zones.keys().cloned().collect::<Vec<_>>().join(","))),
        Command::Zone(zone) => match workshop.zones.get(zone.trim()) {
            Some(ids) => Reply::Text(ids.iter().map(u64::to_string).collect::<Vec<_>>().join(",")),
            None => Reply::NotFound,
        },
        Command::AddZone(zone) => {
            let zone = zone.trim();
            if zone.is_empty() { Reply::Invalid }
            else if workshop.zones.contains_key(zone) { Reply::Conflict }
            else { workshop.zones.insert(zone.into(), Vec::new()); Reply::Changed }
        }
        Command::RemoveZone(zone) => {
            let zone = zone.trim();
            if zone.is_empty() { return Reply::Invalid; }
            let Some(ids) = workshop.zones.remove(zone) else { return Reply::NotFound; };
            for id in ids { workshop.tools.remove(&id); }
            Reply::Changed
        }
        Command::Tool(id) => match workshop.tools.get(&id) {
            Some(tool) => Reply::Text(format!("{}|{}|{}", tool.id, tool.name, tool.zone)),
            None => Reply::NotFound,
        },
        Command::AddTool { id, name, zone } => {
            let name = name.trim(); let zone = zone.trim();
            if name.is_empty() || zone.is_empty() { return Reply::Invalid; }
            if workshop.tools.contains_key(&id) { return Reply::Conflict; }
            let Some(ids) = workshop.zones.get_mut(zone) else { return Reply::NotFound; };
            ids.push(id);
            workshop.tools.insert(id, Tool { id, name: name.into(), zone: zone.into() });
            Reply::Changed
        }
        Command::RemoveTool(id) => {
            let Some(tool) = workshop.tools.remove(&id) else { return Reply::NotFound; };
            if let Some(ids) = workshop.zones.get_mut(&tool.zone) { ids.retain(|x| *x != id); }
            Reply::Changed
        }
    }
}
